# ----- 顯示函式（task2a 的 buffer-blit 加速版，直接呼叫即可）-----
from framebuf import FrameBuffer, MONO_HLSB, RGB565


def draw_char(disp, ch, x, y, color, scale=1):
    """在 ILI9341 上畫一個中文字（單色字模 → RGB565 一次 blit）。"""
    data, w, h = CHARS[ch]
    src = FrameBuffer(bytearray(data), w, h, MONO_HLSB)
    ow, oh = w * scale, h * scale
    buf = bytearray(ow * oh * 2)
    dst = FrameBuffer(buf, ow, oh, RGB565)
    # ILI9341 吃 big-endian，framebuf 存 little-endian → 互換
    c = ((color & 0xFF) << 8) | ((color & 0xFF00) >> 8)
    for sy in range(h):
        for sx in range(w):
            if src.pixel(sx, sy):
                for dy in range(scale):
                    for dx in range(scale):
                        dst.pixel(sx * scale + dx, sy * scale + dy, c)
    disp._window_and_data(x, y, x + ow - 1, y + oh - 1, buf)


def draw_title(disp, x, y, color, scale=1, per_row=5, gap_y=6):
    """畫整個標題「大城北游泳池空汙偵測」，每 per_row 字換一列。"""
    cw = FONT_W * scale
    ch_h = FONT_H * scale
    for i, ch in enumerate(TITLE):
        row, col = i // per_row, i % per_row
        draw_char(disp, ch, x + col * cw, y + row * (ch_h + gap_y), color, scale)
